import java.lang.reflect.*;
import java.util.*;

public class Main {
    static class BD { String name; Class<?> cls; java.util.List<String> deps = new java.util.ArrayList<>(); }

    static class Container {
        java.util.Map<String, BD> defs = new java.util.HashMap<>();
        java.util.Map<String, Object> singletonObjects = new java.util.HashMap<>();
        java.util.Map<String, Object> earlySingletonObjects = new java.util.HashMap<>();
        java.util.Map<String, ObjectFactory> singletonFactories = new java.util.HashMap<>();
        java.util.Set<String> creating = new java.util.HashSet<>();

        interface ObjectFactory { Object getObject(); }

        void register(String name, Class<?> cls, String... deps) {
            BD bd = new BD(); bd.name = name; bd.cls = cls;
            for (String d : deps) bd.deps.add(d);
            defs.put(name, bd);
        }

        Object getBean(String name) throws Exception {
            if (singletonObjects.containsKey(name)) return singletonObjects.get(name);
            if (earlySingletonObjects.containsKey(name)) return earlySingletonObjects.get(name);
            if (singletonFactories.containsKey(name)) {
                Object early = singletonFactories.get(name).getObject();
                earlySingletonObjects.put(name, early);
                singletonFactories.remove(name);
                return early;
            }
            return doCreate(name);
        }

        Object doCreate(String name) throws Exception {
            if (creating.contains(name)) throw new RuntimeException("circular dependency cannot be resolved: " + name);
            creating.add(name);
            BD bd = defs.get(name);
            Object bean = bd.cls.getDeclaredConstructor().newInstance();
            final Object ref = bean;
            singletonFactories.put(name, () -> ref);
            for (String dep : bd.deps) {
                Object depBean = getBean(dep);
                Field f = bean.getClass().getDeclaredField(dep);
                f.setAccessible(true);
                f.set(bean, depBean);
            }
            singletonObjects.put(name, bean);
            earlySingletonObjects.remove(name);
            singletonFactories.remove(name);
            creating.remove(name);
            return bean;
        }
    }

    static class A { B b; }
    static class B { A a; }

    public static void main(String[] args) throws Exception {
        Container c = new Container();
        c.register("a", A.class, "b");
        c.register("b", B.class, "a");
        A a = (A) c.getBean("a");
        System.out.println("a.b not null: " + (a.b != null));
        System.out.println("b.a == a: " + (a.b.a == a));
        System.out.println("resolved via 3-level cache: true");
    }
}
